                getDeposit[_depositNonce].tokens[0],
                getDeposit[_depositNonce].amounts[0],
                _normalizeDecimals(
                    getDeposit[_depositNonce].deposits[0], ERC20(getDeposit[_depositNonce].tokens[0]).decimals()
                ),
                _toChain,
                _params,
                msg.value.toUint128(),
                _remoteExecutionGas
            );
        }
    } else if (uint8(getDeposit[_depositNonce].hTokens.length) > 1) {
        //Nonce
        uint32 nonce = _depositNonce;

        if (_isSigned) {
            packedData = abi.encodePacked(
                bytes1(0x06),
                msg.sender,
                uint8(getDeposit[_depositNonce].hTokens.length),
                nonce,
                getDeposit[nonce].hTokens,
                getDeposit[nonce].tokens,
                getDeposit[nonce].amounts,
                _normalizeDecimalsMultiple(getDeposit[nonce].deposits, getDeposit[nonce].tokens),
                _toChain,
                _params,
                msg.value.toUint128(),
                _remoteExecutionGas
            );
        } else {
            packedData = abi.encodePacked(
                bytes1(0x03),
                uint8(getDeposit[nonce].hTokens.length),
                _depositNonce,
                getDeposit[nonce].hTokens,
                getDeposit[nonce].tokens,
                getDeposit[nonce].amounts,
                _normalizeDecimalsMultiple(getDeposit[nonce].deposits, getDeposit[nonce].tokens),
                _toChain,
                _params,
                msg.value.toUint128(),
                _remoteExecutionGas
            );
        }
    }

    //Wrap the gas allocated for omnichain execution.
    wrappedNativeToken.deposit{value: msg.value}();

    //Deposit Gas to Port
    _depositGas(msg.value.toUint128());

    //Ensure success Status
    getDeposit[_depositNonce].status = DepositStatus.Success;

    //Update Deposited Gas
    getDeposit[_depositNonce].depositedGas = msg.value.toUint128();

    //Perform Call
    _performCall(packedData);
}

function retrieveDeposit(uint32 _depositNonce) external payable lock requiresFallbackGas {
    //Encode Data for cross-chain call.
    bytes memory packedData = abi.encodePacked(bytes1(0x08), _depositNonce, msg.value.toUint128(), uint128(0));

    //Update State and Perform Call
    _sendRetrieveOrRetry(packedData);
}

function checkParams(address _localPortAddress, DepositParams memory _dParams, uint24 _fromChain)
    internal
    view
    returns (bool)
{
    if (
        (_dParams.amount < _dParams.deposit) //Deposit can't be greater than amount.
            || (_dParams.amount > 0 && !IPort(_localPortAddress).isLocalToken(_dParams.hToken, _fromChain)) //Check local exists.
            || (_dParams.deposit > 0 && !IPort(_localPortAddress).isUnderlyingToken(_dParams.token, _fromChain)) //Check underlying exists.
    ) {
        return false;
    }
    return true;
}

function init(uint256 amount0Desired, uint256 amount1Desired, address receiver)
    external
    virtual
    nonReentrant
    returns (uint256 shares, uint256 amount0, uint256 amount1)
{
    if (initialized) revert AlreadyInitialized();

    {
        // Own Scope to avoid stack to deep
        int24 _tickSpacing = tickSpacing; // Saves an extra SLOAD
        int24 baseThreshold = _tickSpacing * optimizer.tickRangeMultiplier();
        (, int24 currentTick,,,,,) = pool.slot0();
        int24 tickFloor = PoolVariables.floor(currentTick, _tickSpacing);

        int24 _tickLower = tickFloor - baseThreshold; // Saves an extra SLOAD
        int24 _tickUpper = tickFloor + baseThreshold; // Saves an extra SLOAD
        PoolVariables.checkRange(_tickLower, _tickUpper); // Check ticks also for overflow/underflow
        tickLower = _tickLower;
        tickUpper = _tickUpper;
    }

    (ERC20 _token0, ERC20 _token1) = (token0, token1);
    address(_token0).safeTransferFrom(msg.sender, address(this), amount0Desired);
    address(_token1).safeTransferFrom(msg.sender, address(this), amount1Desired);

    INonfungiblePositionManager _nonfungiblePositionManager = nonfungiblePositionManager; // Saves an extra SLOAD

    address(_token0).safeApprove(address(_nonfungiblePositionManager), type(uint256).max);
    address(_token1).safeApprove(address(_nonfungiblePositionManager), type(uint256).max);

    uint128 _liquidity;
    uint256 _tokenId;
    (_tokenId, _liquidity, amount0, amount1) = _nonfungiblePositionManager.mint(
        INonfungiblePositionManager.MintParams({
            token0: address(_token0),
            token1: address(_token1),
            fee: poolFee,
            tickLower: tickLower,
            tickUpper: tickUpper,
            amount0Desired: amount0Desired,
            amount1Desired: amount1Desired,
            amount0Min: 0,
            amount1Min: 0,
            recipient: address(this),
            deadline: block.timestamp
        })
    );

    if (amount0 == 0 && amount1 == 0) revert AmountsAreZero();

    shares = _liquidity * MULTIPLIER;
    liquidity = _liquidity;
    tokenId = _tokenId;

    _mint(receiver, shares);
    if (totalSupply > optimizer.maxTotalSupply()) revert ExceedingMaxTotalSupply();

    emit Initialize(tokenId, msg.sender, receiver, amount0, amount1, shares);

    afterDeposit(_tokenId);
    initialized = true;

    // Refund in both assets.
    if (amount0 < amount0Desired) {
        uint256 refund0 = amount0Desired - amount0;
        address(_token0).safeTransfer(msg.sender, refund0);
    }

    if (amount1 < amount1Desired) {
        uint256 refund1 = amount1Desired - amount1;
        address(_token1).safeTransfer(msg.sender, refund1);
    }
}

modifier checkDeviation() {
    ITalosOptimizer _optimizer = optimizer;
    pool.checkDeviation(_optimizer.maxTwapDeviation(), _optimizer.twapDuration());
    _;
}

